public class Partial_with_TriageGen0Test {

    @Test(expected = IllegalArgumentException.class)
    public void testWith_NullFieldType_ThrowsException() {
        Partial partial = new Partial(org.joda.time.impl.DefaultChronology.getChronology());
        partial.with(null, 10);
    }

    @Test
    public void testWith_ExistingField_DifferentValue() {
        DateTimeFieldType yearType = DateTimeFieldType.yearOfStandardDateTime();
        Partial partial = new Partial(yearType, 2020);

        Partial updated = partial.with(yearType, 2021);

        assertNotSame(partial, updated);
        assertEquals(2021, updated.getValue(0));
        assertEquals(1, updated.size());
    }

    @Test
    public void testWith_ExistingField_SameValue_ReturnsThis() {
        DateTimeFieldType yearType = DateTimeFieldType.yearOfStandardDateTime();
        Partial partial = new Partial(yearType, 2020);

        Partial updated = partial.with(yearType, 2020);

        assertSame(partial, updated);
    }

    @Test
    public void testWith_NewField_InsertionAtStart() {
        // Using standard types to ensure unitField.isSupported() logic is exercised
        DateTimeFieldType yearType = DateTimeFieldType.yearOfStandardDateTime();
        DateTimeFieldType monthType = DateTimeFieldType.monthOfYear();

        // Create partial with Month, then add Year (Year is larger unit than Month)
        // The logic sorts by unitField comparison. Larger units come first in the array.
        Partial partial = new Partial(monthType, 1);
        Partial updated = partial.with(yearType, 2023);

        assertEquals(2, updated.size());
        // Check if Year is at index 0 because it's "larger"
        assertEquals(yearType, updated.getFieldType(0));
        assertEquals(2023, updated.getValue(0));
        assertEquals(monthType, updated.getFieldType(1));
        assertEquals(1, updated.getValue(1));
    }

    @Test
    public void testWith_NewField_InsertionMiddle() {
        DateTimeFieldType yearType = DateTimeFieldType.yearOfStandardDateTime();
        DateTimeFieldType monthType = DateTimeFieldType.monthOfYear();
        DateTimeFieldType dayType = DateTimeFieldType.dayOfMonth();

        // Start with Year and Day
        Partial partial = new Partial(new DateTimeFieldType[]{yearType, dayType}, new int[]{2020, 15});

        // Add Month (should go between Year and Day)
        Partial updated = partial.with(monthType, 5);

        assertEquals(3, updated.size());
        assertEquals(yearType, updated.getFieldType(0));
        assertEquals(monthType, updated.getFieldType(1));
        assertEquals(dayType, updated.getFieldType(2));

        assertEquals(2020, updated.getValue(0));
        assertEquals(5, updated.getValue(1));
        assertEquals(15, updated.getValue(2));
    }

    @Test
    public void testWith_NewField_InsertionAtEnd() {
        DateTimeFieldType yearType = DateTimeFieldType.yearOfStandardDateTime();
        DateTimeFieldType monthType = DateTimeFieldType.monthOfYear();

        Partial partial = new Partial(yearType, 2020);
        // Add month (smaller unit than year)
        Partial updated = partial.with(monthType, 12);

        assertEquals(2, updated.size());
        assertEquals(yearType, updated.getFieldType(0));
        assertEquals(monthType, updated.getFieldType(1));
    }

    @Test
    public void testWith_NewField_SameUnitDifferentRange() {
        // This targets the 'else if (compare == 0)' branch where rangeField is compared
        // We need two different field types that have the same duration unit but different ranges
        // In Joda, Millisecond and Millisecond are same unit. 
        // Let's try to simulate via custom types if possible, or use standard ones.
        // Since we can't easily define custom DateTimeFieldTypes without complex mocks, 
        // we rely on the fact that most standard types have different ranges or units.

        DateTimeFieldType yearType = DateTimeFieldType.yearOfStandardDateTime();
        DateTimeFieldType monthType = DateTimeFieldType.monthOfYear();

        Partial partial = new Partial(yearType, 2020);
        Partial updated = partial.with(monthType, 1);

        assertNotNull(updated);
        assertEquals(2, updated.size());
    }

